// Gabarits des grandes fenêtres modales, générés ici plutôt qu'écrits en
// dur dans index.html (retour utilisateur : "corrigé le problème de code
// html trop imposant... fais pareil pour les autres grosses modales" — même
// principe déjà appliqué à #viewModal, voir le tout début de
// js/render-view-modal.js).
//
// Chargé en tout premier (avant popup.js et tout le reste, voir index.html)
// pour que ces éléments existent déjà quand n'importe quel autre script les
// référence — y compris via un getElementById() de premier niveau, exécuté
// immédiatement au chargement du fichier plutôt que dans une fonction
// appelée plus tard. Un seul fichier centralisé plutôt qu'une injection
// répartie dans le fichier "propriétaire" de chaque modale (comme pour
// #viewModal) : avec ~12 modales possédées par des fichiers différents
// (modal-core.js, js/requests.js, js/armoireConfig.js...), un point d'entrée
// unique évite de devoir vérifier, pour chacune, quel fichier la référence
// en premier au chargement — la seule garantie nécessaire est que CE fichier
// s'exécute avant tous les autres.
//
// Seul le contenu INTÉRIEUR de chaque grande fenêtre a été déplacé ici —
// la coquille (l'élément avec son id et son style d'origine, sur laquelle le
// reste du JS bascule .style.display / .classList) reste dans index.html,
// inchangée.
(function _spiInjectModalTemplates(){
  function set(id, html){
    var el = document.getElementById(id);
    if(el) el.innerHTML = html;
  }
  // ── Fenêtre d'ajout/modification produit (#modalOverlay) ──
  set("modalOverlay", "\n  <div class=\"modal\">\n    <div class=\"modal-head\">\n      <h3 id=\"modalTitle\">Ajouter un produit</h3>\n      <button class=\"close sans\" id=\"modalClose\">&times;</button>\n    </div>\n    <div class=\"modal-body\">\n\n      <div class=\"field-row\">\n        <div class=\"field\">\n          <label for=\"fBrand\">Marque</label>\n          <div class=\"autocomplete-wrap\"><input type=\"text\" id=\"fBrand\" placeholder=\"ex. Acme Studio\" autocomplete=\"off\">\n          <div class=\"autocomplete-suggestions\" id=\"brandSuggestions\"></div></div>\n        </div>\n        <div class=\"field\">\n          <div style=\"display:flex;align-items:center;gap:5px;margin-bottom:3px;\">\n            <label for=\"fRef\" style=\"margin:0;\">Référence</label>\n            <span class=\"ref-dup-icon\" id=\"refDupIcon\"><i class=\"ti ti-info-circle-filled\"></i><span class=\"ref-dup-tooltip\" id=\"refDupTooltip\"></span></span>\n          </div>\n          <input type=\"text\" id=\"fRef\" placeholder=\"ex. AS-2291-BLK\">\n          <div id=\"refCheckMsg\" class=\"ref-check-msg\"></div>\n          <div id=\"refDupBanner\" class=\"ref-dup-banner\"></div>\n        </div>\n      </div>\n\n      <div class=\"field-row\">\n        <div class=\"field\">\n          <label for=\"fFamily\">Famille de produit</label>\n          <div class=\"autocomplete-wrap\"><input type=\"text\" id=\"fFamily\" placeholder=\"ex. Sacs &amp; bagagerie\" autocomplete=\"off\">\n          <div class=\"autocomplete-suggestions\" id=\"familySuggestions\"></div></div>\n          <div class=\"family-icon-row\" id=\"familyIconRow\">\n            <div class=\"family-icon-label\">Icône de la famille</div>\n            <div class=\"family-icon-preview\" id=\"familyIconPreview\"><img src=\"assets/icons/families/svg-generique.png\" alt=\"\" aria-hidden=\"true\"></div>\n            <button type=\"button\" class=\"family-icon-picker-btn\" id=\"familyIconPickerBtn\">\n              <i class=\"ti ti-grid-dots\"></i> Choisir une icône\n            </button>\n          </div>\n        </div>\n        <div class=\"field\">\n          <label for=\"fSeries\">Série</label>\n          <div class=\"autocomplete-wrap\"><input type=\"text\" id=\"fSeries\" placeholder=\"ex. Voyager\" autocomplete=\"off\">\n          <div class=\"autocomplete-suggestions\" id=\"seriesSuggestions\"></div></div>\n        </div>\n      </div>\n\n      <div class=\"field\">\n        <label for=\"fSupplier\">Fournisseur</label>\n        <div class=\"autocomplete-wrap\"><input type=\"text\" id=\"fSupplier\" placeholder=\"ex. Dupont Distribution\" autocomplete=\"off\">\n        <div class=\"autocomplete-suggestions\" id=\"supplierSuggestions\"></div></div>\n      </div>\n      <div class=\"field\">\n        <label for=\"fLeadTime\">Délai de disponibilité</label>\n        <input type=\"text\" id=\"fLeadTime\" placeholder=\"ex. 3-5 jours, 2 semaines, sur commande...\">\n      </div>\n      <div class=\"field field-checkbox\">\n        <div class=\"checkbox-row\">\n          <input type=\"checkbox\" id=\"f3dAvailable\">\n          <span class=\"checkbox-label\">3DEXPERIENCE</span>\n          <input type=\"checkbox\" id=\"fEssential\" style=\"margin-left:18px;\">\n          <span class=\"checkbox-label\">Essentiel</span>\n        </div>\n      </div>\n      <div class=\"field\" id=\"f3dLinkRow\" style=\"display:none;\">\n        <label for=\"f3dLink\">Lien 3DEXPERIENCE</label>\n        <input type=\"url\" id=\"f3dLink\" placeholder=\"https://...\">\n      </div>\n\n      <!-- ===== CHAMP SUGGESTIONS ===== -->\n      <div class=\"field\" id=\"fSuggestionsRow\">\n        <label>Produits suggérés</label>\n        <div style=\"display:flex;gap:8px;align-items:flex-start;\">\n          <div class=\"sug-autocomplete-wrap\" style=\"position:relative;flex:1;min-width:0;\">\n            <input type=\"text\" id=\"fSuggestionsSearch\" placeholder=\"Rechercher par réf, nom, famille ou marque…\" autocomplete=\"off\" style=\"width:100%;\">\n            <div class=\"autocomplete-suggestions\" id=\"fSuggestionsDrop\" style=\"display:none;\"></div>\n          </div>\n          <button type=\"button\" id=\"btnSugBrowse\" class=\"sug-browse-btn\" title=\"Parcourir le catalogue par catégorie\">\n            <i class=\"ti ti-category-2\"></i>\n          </button>\n        </div>\n        <div class=\"sug-chips\" id=\"fSuggestionsChips\"></div>\n      </div>\n      <!-- ===== FIN CHAMP SUGGESTIONS ===== -->\n\n      <!-- ===== CHAMP PIÈCES DE RECHANGE ===== -->\n      <div class=\"field\" id=\"fSparePartsRow\">\n        <label>Pièces de rechange</label>\n        <div style=\"display:flex;gap:8px;align-items:flex-start;\">\n          <div class=\"sug-autocomplete-wrap\" style=\"position:relative;flex:1;min-width:0;\">\n            <input type=\"text\" id=\"fSparePartsSearch\" placeholder=\"Rechercher par réf, nom, famille ou marque…\" autocomplete=\"off\" style=\"width:100%;\">\n            <div class=\"autocomplete-suggestions\" id=\"fSparePartsDrop\" style=\"display:none;\"></div>\n          </div>\n          <button type=\"button\" id=\"btnSparePartsBrowse\" class=\"sug-browse-btn\" title=\"Parcourir le catalogue par catégorie\">\n            <i class=\"ti ti-category-2\"></i>\n          </button>\n        </div>\n        <div class=\"sug-chips\" id=\"fSparePartsChips\"></div>\n      </div>\n      <!-- ===== FIN CHAMP PIÈCES DE RECHANGE ===== -->\n\n      <!-- ===== CHAMP CARACTÉRISTIQUES (fenêtre dédiée) ===== -->\n      <div class=\"field\" id=\"fSpecsRow\">\n        <label>Caractéristiques techniques <span style=\"font-size:11px;color:var(--ink-soft);font-weight:400;\">(ex: nombre d'entrées, connecteur…)</span></label>\n        <button type=\"button\" id=\"btnOpenSpecs\" style=\"display:flex;align-items:center;gap:8px;padding:10px 16px;border-radius:9px;border:1.5px solid var(--copper);background:var(--paper-card);color:var(--copper);font-size:13px;font-weight:600;cursor:pointer;font-family:var(--font-sans);width:100%;\">\n          <i class=\"ti ti-list-details\" style=\"font-size:17px;\"></i>\n          <span id=\"btnOpenSpecsLabel\">Ajouter des caractéristiques</span>\n        </button>\n      </div>\n      <!-- ===== FIN CHAMP CARACTÉRISTIQUES ===== -->\n\n      <div class=\"tabs\" id=\"productExtractTabs\">\n        <button class=\"tab-btn tab-btn-copper active\" data-tab=\"auto\">Extraction automatique</button>\n        <button class=\"tab-btn tab-btn-copper\" data-tab=\"manual\">Saisie manuelle</button>\n      </div>\n\n      <div class=\"tab-pane active\" id=\"tab-auto\">\n        <div class=\"field\">\n          <label for=\"fUrl\">URL de la fiche produit</label>\n          <!-- Cet onglet entier n'est plus jamais affiché sur mobile/tablette\n               (voir #productExtractTabs dans css/styles.css) — plus besoin\n               de variante mobile ici, un seul bouton pour tous les cas où\n               cette zone reste visible (desktop uniquement). -->\n          <input type=\"text\" id=\"fUrl\" placeholder=\"https://www.marque.com/produit/...\" style=\"width:100%;\">\n          <div style=\"display:flex;gap:8px;align-items:center;margin-top:6px;\">\n            <button type=\"button\" id=\"btnExtractFromUrl\" class=\"secondary\" style=\"white-space:nowrap;padding:9px 12px;\">\n              ↓ Extraire depuis l'URL\n            </button>\n          </div>\n          <div class=\"hint\" id=\"extractUrlHint\" style=\"display:none;margin-top:5px;\"></div>\n        </div>\n        <!-- Desktop uniquement : zone code source -->\n        <div class=\"field html-source-zone\">\n          <label style=\"display:flex;align-items:center;gap:8px;cursor:pointer;\">\n            <input type=\"checkbox\" id=\"chkShowHtml\" style=\"width:16px;height:16px;\">\n            Code source de la page produit (alternative)\n          </label>\n          <div id=\"htmlSourceContent\" style=\"display:none;margin-top:8px;\">\n            <textarea id=\"fHtml\" rows=\"6\" placeholder=\"Ouvrez la fiche produit sur le site → clic droit → « Afficher le code source de la page » (ou Ctrl+U) → Ctrl+A, Ctrl+C → collez ici.\"></textarea>\n            <div class=\"hint\">Le navigateur ne peut pas aller chercher une autre page web tout seul (sécurité). En collant le code source ici, l'outil retrouve automatiquement l'image, le nom, la description et le prix depuis les informations standard de la page (balises Open Graph / données produit).</div>\n            <button class=\"secondary\" id=\"btnExtract\" type=\"button\" style=\"margin-top:8px;\">Extraire les informations</button>\n            <div class=\"extract-status\" id=\"extractStatus\"></div>\n          </div>\n        </div>\n      </div>\n\n      <div class=\"tab-pane\" id=\"tab-manual\">\n        <div class=\"photo-row\">\n          <div class=\"photo-preview\" id=\"photoPreview\"><span class=\"hint sans\" style=\"padding:6px;text-align:center;\">aperçu</span></div>\n          <div class=\"field\" style=\"flex:1; margin-bottom:0;\">\n            <label for=\"fPhoto\">URL de la photo</label>\n            <input type=\"text\" id=\"fPhoto\" placeholder=\"https://...\">\n          </div>\n        </div>\n        <!-- Galerie de sélection — visible uniquement si plusieurs photos extraites -->\n        <div class=\"photo-gallery\" id=\"photoGallery\">\n          <div class=\"photo-gallery-label\">Choisir une photo parmi les images trouvées sur la page</div>\n          <div class=\"photo-gallery-grid\" id=\"photoGalleryGrid\"></div>\n        </div>\n        <div class=\"field\" style=\"margin-top:14px;\">\n          <label for=\"fName\">Nom du produit</label>\n          <input type=\"text\" id=\"fName\" placeholder=\"ex. Sac à dos Voyager 24L\">\n        </div>\n        <div class=\"field\">\n          <label for=\"fDesc\">Description</label>\n          <textarea id=\"fDesc\" rows=\"3\" placeholder=\"Description courte du produit\"></textarea>\n        </div>\n        <div class=\"field\">\n          <label for=\"fTags\">Tags</label>\n          <input type=\"text\" id=\"fTags\" placeholder=\"ex. éclairage, installation, borne\">\n          <div class=\"hint\">Séparez plusieurs tags par des virgules pour mieux retrouver le produit.</div>\n          <div class=\"tag-suggestions\" id=\"tagSuggestions\" style=\"display:none;\"></div>\n        </div>\n        <div class=\"field\">\n          <!-- Mode création : champ texte visible -->\n          <div id=\"priceCreateRow\">\n            <label for=\"fPrice\">Prix catalogue (€)</label>\n            <input type=\"text\" id=\"fPrice\" placeholder=\"ex. 89,90 (le € est ajouté automatiquement)\">\n            <div class=\"hint\">Saisissez juste le montant, le symbole € est ajouté automatiquement. <span id=\"pricePreview\"></span></div>\n          </div>\n          <!-- Mode édition : affichage + bouton modale -->\n          <div id=\"priceDisplayRow\" style=\"display:none;align-items:center;justify-content:space-between;gap:8px;padding:8px 12px;border:1px solid var(--line);border-radius:6px;background:var(--paper);\">\n            <div>\n              <div style=\"font-size:11px;text-transform:uppercase;letter-spacing:.07em;color:var(--ink-soft);margin-bottom:1px;\">Prix actuel</div>\n              <div style=\"font-size:15px;font-weight:600;color:var(--ink);\" id=\"priceDisplayVal\">—</div>\n            </div>\n            <button type=\"button\" id=\"btnOpenPriceModal\" style=\"display:none;white-space:nowrap;padding:7px 12px;border:1px solid var(--line);border-radius:6px;background:var(--paper-card);color:var(--ink);cursor:pointer;font-size:13px;display:flex;align-items:center;gap:6px;\">\n              <i class=\"ti ti-history\" aria-hidden=\"true\"></i> Modifier les prix\n            </button>\n          </div>\n        </div>\n\n        <!-- Zone prix de vente — visible uniquement en mode création -->\n        <div class=\"field selling-price-zone\" id=\"sellingPriceZone\" style=\"display:none;\">\n          <label for=\"fSellingPrice\">Votre prix d'achat / prix de vente (€)</label>\n          <input type=\"text\" id=\"fSellingPrice\" placeholder=\"ex. 89,90 — votre prix négocié\">\n          <div class=\"hint\" id=\"sellingPriceHint\"></div>\n        </div>\n      </div>\n\n      <!-- ===== SECTION PDF/IMAGES FORMULAIRE ===== -->\n      <div id=\"modalPdfSection\" style=\"display:none;border-top:1px solid var(--line);padding-top:14px;margin-top:4px;\">\n        <div id=\"modalPdfSectionTitle\" style=\"font-size:11px;font-weight:700;color:var(--ink-soft);letter-spacing:.06em;text-transform:uppercase;margin-bottom:8px;\">Documents</div>\n        <!-- Liste des fichiers existants (multi-doc) -->\n        <div id=\"modalPdfList\" style=\"display:flex;flex-direction:column;gap:6px;margin-bottom:8px;\"></div>\n        <!-- Zone d'ajout -->\n        <label id=\"modalPdfUpload\" style=\"display:none;align-items:center;gap:8px;padding:10px 14px;border-radius:8px;border:1.5px dashed var(--line);background:var(--paper);color:var(--ink-soft);font-size:13px;cursor:pointer;font-family:inherit;\">\n          <i class=\"ti ti-file-plus\" style=\"font-size:18px;color:var(--copper);\"></i>\n          Ajouter un ou plusieurs PDF/images\n          <input type=\"file\" id=\"modalPdfInput\" accept=\".pdf,application/pdf,image/*\" multiple style=\"position:absolute;width:0;height:0;opacity:0;pointer-events:none;\">\n        </label>\n      </div>\n      <!-- ===== FIN SECTION PDF FORMULAIRE ===== -->\n\n      <!-- ===== DOCUMENTS JOINTS À LA DEMANDE (mode révision, visionnage seul) ===== -->\n      <div id=\"modalReqDocsSection\" style=\"display:none;border-top:1px solid var(--line);padding-top:14px;margin-top:4px;\">\n        <div style=\"font-size:11px;font-weight:700;color:var(--ink-soft);letter-spacing:.06em;text-transform:uppercase;margin-bottom:8px;\">Documents joints à la demande</div>\n        <div id=\"modalReqDocsList\" style=\"display:flex;flex-direction:column;gap:6px;\"></div>\n      </div>\n      <!-- ===== FIN DOCUMENTS JOINTS À LA DEMANDE ===== -->\n\n    </div>\n    <div id=\"modalNoSyncBanner\" style=\"display:none;align-items:flex-start;gap:8px;background:#FEE2E2;border-top:1px solid #FECACA;color:#991B1B;padding:10px 20px;font-size:12.5px;line-height:1.4;\">\n      <i class=\"ti ti-cloud-off\" style=\"font-size:16px;flex-shrink:0;margin-top:1px;\"></i>\n      <span id=\"modalNoSyncBannerText\"></span>\n    </div>\n    <div class=\"modal-foot\" id=\"modalFoot\">\n      <div class=\"left-foot\" id=\"modalLeftFoot\"></div>\n      <div style=\"display:flex; gap:10px;\">\n        <button class=\"secondary\" id=\"btnCancel\" type=\"button\">Annuler</button>\n        <button class=\"copper\" id=\"btnSave\" type=\"button\">Enregistrer le produit</button>\n        <!-- Boutons de la vue \"demande produit\" verrouillée (consultation\n             avant décision) — remplacent Annuler/Enregistrer tant que\n             window._reviewLocked est vrai. \"Modifier\" déverrouille les\n             champs SUR CETTE MÊME fenêtre plutôt que d'en ouvrir une autre\n             (retour utilisateur : rester sur la même page). -->\n        <button class=\"secondary\" id=\"btnReviewRefuse\" type=\"button\" style=\"display:none;color:#991B1B;border-color:#FECACA;\"><i class=\"ti ti-x\"></i> Refuser</button>\n        <button class=\"secondary\" id=\"btnReviewUnlock\" type=\"button\" style=\"display:none;\"><i class=\"ti ti-pencil\"></i> Modifier</button>\n        <button class=\"copper\" id=\"btnReviewAccept\" type=\"button\" style=\"display:none;\"><i class=\"ti ti-check\"></i> Accepter</button>\n      </div>\n    </div>\n  </div>\n");
  // ── Import Excel (#xlsxImportOverlay) ──
  set("xlsxImportOverlay", "\n  <div style=\"\n    background:var(--paper-card);border-radius:12px;\n    width:100%;max-width:720px;max-height:85vh;\n    display:flex;flex-direction:column;\n    box-shadow:0 24px 80px rgba(0,0,0,.3);\n    overflow:hidden;\n    font-family:var(--font-sans);\n  \">\n    <div style=\"padding:20px 24px 16px;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;\">\n      <div>\n        <div style=\"font-size:18px;font-weight:700;color:var(--ink);\">Aperçu de l'import Excel</div>\n        <div style=\"font-size:13px;color:var(--ink-soft);margin-top:2px;\" id=\"xlsxImportSummary\"></div>\n      </div>\n      <button id=\"btnCloseXlsxImport\" type=\"button\" aria-label=\"Fermer\" style=\"background:none;border:none;font-size:22px;color:var(--ink-soft);cursor:pointer;padding:4px 8px;\">✕</button>\n    </div>\n    <div style=\"overflow-y:auto;flex:1;padding:16px 24px;\">\n      <div style=\"overflow-x:auto;\">\n        <table id=\"xlsxPreviewTable\" style=\"width:100%;min-width:480px;border-collapse:collapse;font-size:13px;\">\n          <thead id=\"xlsxPreviewHead\"></thead>\n          <tbody id=\"xlsxPreviewBody\"></tbody>\n        </table>\n      </div>\n    </div>\n    <div style=\"padding:14px 24px 18px;border-top:1px solid var(--line);display:flex;gap:10px;justify-content:flex-end;align-items:center;\">\n      <span id=\"xlsxImportInfo\" style=\"font-size:13px;color:var(--ink-soft);flex:1;\"></span>\n      <button class=\"secondary\" type=\"button\" id=\"btnCancelXlsxImport\">Annuler</button>\n      <button class=\"copper\" id=\"btnConfirmXlsxImport\">✓ Confirmer l'import</button>\n    </div>\n  </div>\n");
  // ── Panneau Demandes (#requestsOverlay) ──
  set("requestsOverlay", "\n  <div id=\"requestsPanel\" style=\"background:var(--paper-card);border-radius:14px;width:100%;max-width:560px;height:85vh;display:flex;flex-direction:column;box-shadow:0 24px 80px rgba(0,0,0,.4);overflow:hidden;\">\n    <!-- Header -->\n    <div style=\"display:flex;align-items:center;justify-content:space-between;padding:18px 20px;border-bottom:1px solid var(--line);flex-shrink:0;\">\n      <div style=\"display:flex;align-items:center;gap:10px;\">\n        <!-- Flèche \"retour au menu\" (voir js/actions-core.js — window._setHeaderBackMode)\n             — masquée par défaut, affichée uniquement quand ce panneau a été\n             ouvert depuis le tiroir menu mobile, à la place de la croix de\n             droite, à gauche du titre comme les sous-pages de Paramètres.\n             Même bouton (.win-back-btn) qu'ailleurs, pour tomber exactement\n             au même endroit. -->\n        <button id=\"requestsBackBtn\" class=\"win-back-btn\" aria-label=\"Retour au menu\"><i class=\"ti ti-arrow-left\" aria-hidden=\"true\"></i></button>\n        <i class=\"ti ti-bell\" style=\"font-size:20px;color:#194093;\"></i>\n        <span style=\"font-size:15px;font-weight:700;color:var(--ink);\">Demandes en attente</span>\n      </div>\n      <button id=\"requestsPanelClose\" style=\"background:none;border:none;font-size:22px;cursor:pointer;color:var(--ink-soft);padding:2px 6px;line-height:1;\">✕</button>\n    </div>\n    <!-- Onglets Demandes produit / Bugs signalés -->\n    <div id=\"requestsTabs\" class=\"tabs\" style=\"padding:12px 20px 10px;border-bottom:1px solid var(--line);flex-shrink:0;margin-bottom:0;\">\n      <button class=\"req-tab tab-btn tab-btn-copper active\" data-tab=\"product\" id=\"reqTabProduct\"><i class=\"ti ti-package\"></i> Demandes produit</button>\n      <button class=\"req-tab tab-btn tab-btn-copper\" data-tab=\"bug\" id=\"reqTabBug\"><i class=\"ti ti-bug\"></i> Bugs signalés</button>\n    </div>\n    <!-- Corps -->\n    <div id=\"requestsBody\" style=\"flex:1;overflow-y:auto;\"></div>\n    <!-- Footer admin -->\n    <div id=\"requestsFooter\" style=\"display:none;padding:14px 20px;border-top:1px solid var(--line);display:flex;gap:8px;justify-content:flex-end;flex-shrink:0;\">\n      <button id=\"btnAcceptAllRequests\" class=\"copper\" style=\"padding:8px 18px;border-radius:8px;font-size:13px;cursor:pointer;font-family:inherit;\">\n        <i class=\"ti ti-check\"></i> Tout accepter\n      </button>\n      <button id=\"btnRefuseAllRequests\" style=\"padding:8px 18px;border-radius:8px;border:1px solid var(--line);background:var(--paper-card);color:var(--ink);font-size:13px;cursor:pointer;font-family:inherit;\">\n        <i class=\"ti ti-x\"></i> Tout refuser\n      </button>\n    </div>\n  </div>\n");
  // ── Détail Demande (#reqDetailOverlay) ──
  set("reqDetailOverlay", "\n  <div id=\"reqDetailModal\" style=\"background:var(--paper-card);border-radius:14px;width:100%;max-width:680px;max-height:90vh;display:flex;flex-direction:column;overflow:hidden;box-shadow:0 24px 80px rgba(0,0,0,.4);\">\n    <div style=\"display:flex;align-items:center;justify-content:space-between;padding:16px 20px;border-bottom:1px solid var(--line);flex-shrink:0;\">\n      <div>\n        <div id=\"reqDetailTitle\" style=\"font-size:15px;font-weight:700;color:var(--ink);\"></div>\n        <div id=\"reqDetailSubtitle\" style=\"font-size:12px;color:var(--ink-soft);margin-top:2px;\"></div>\n      </div>\n      <button id=\"reqDetailClose\" style=\"background:none;border:none;font-size:22px;cursor:pointer;color:var(--ink-soft);\">✕</button>\n    </div>\n    <div id=\"reqDetailBody\" style=\"flex:1;overflow-y:auto;padding:20px;\"></div>\n    <div id=\"reqDetailFooter\" style=\"display:flex;gap:8px;justify-content:flex-end;padding:14px 20px;border-top:1px solid var(--line);flex-shrink:0;\">\n      <button id=\"reqDetailRefuse\" class=\"req-btn-refuse\"><i class=\"ti ti-x\"></i> Refuser</button>\n      <button id=\"reqDetailEdit\" style=\"display:none;padding:9px 16px;border-radius:8px;border:1.5px solid var(--line);background:var(--paper-card);color:var(--ink);font-size:13px;font-weight:600;cursor:pointer;font-family:var(--font-sans);display:flex;align-items:center;gap:6px;\"><i class=\"ti ti-pencil\"></i> Modifier</button>\n      <button id=\"reqDetailAccept\" class=\"req-btn-accept\"><i class=\"ti ti-check\"></i> Accepter</button>\n    </div>\n  </div>\n");
  // ── Signaler un bug (#bugReportOverlay) ──
  set("bugReportOverlay", "\n  <div class=\"modal\" style=\"max-width:480px;\">\n    <div class=\"modal-head\">\n      <div class=\"win-header-titlewrap\">\n        <!-- Flèche \"retour au menu\" (voir js/actions-core.js — window._setHeaderBackMode)\n             — masquée par défaut, affichée à gauche du titre uniquement\n             quand cette fenêtre a été ouverte depuis le tiroir menu mobile,\n             à la place de la croix de droite. Même bouton (.win-back-btn) et\n             même structure que Paramètres/Demandes/Comparateur, pour tomber\n             exactement au même endroit qu'ailleurs. -->\n        <button id=\"bugReportBackBtn\" class=\"win-back-btn\" aria-label=\"Retour au menu\"><i class=\"ti ti-arrow-left\" aria-hidden=\"true\"></i></button>\n        <h3><i class=\"ti ti-bug\"></i> Signaler un bug</h3>\n      </div>\n      <button class=\"close sans\" id=\"bugReportCloseBtn\" type=\"button\">&times;</button>\n    </div>\n    <div class=\"modal-body\">\n      <label for=\"bugReportTitle\" style=\"font-size:12.5px;font-weight:600;color:var(--ink-soft);display:block;margin-bottom:6px;\">Titre</label>\n      <input type=\"text\" id=\"bugReportTitle\" placeholder=\"Ex. : Le bouton Enregistrer ne répond pas\" style=\"width:100%;padding:10px 12px;border:1px solid var(--line);border-radius:8px;font-family:var(--font-sans);font-size:13.5px;box-sizing:border-box;margin-bottom:14px;\">\n\n      <label for=\"bugReportSeverity\" style=\"font-size:12.5px;font-weight:600;color:var(--ink-soft);display:block;margin-bottom:6px;\">Gravité</label>\n      <select id=\"bugReportSeverity\" style=\"width:100%;padding:10px 12px;border:1px solid var(--line);border-radius:8px;font-family:var(--font-sans);font-size:13.5px;box-sizing:border-box;margin-bottom:14px;background:var(--paper);color:var(--ink);\">\n        <option value=\"low\">Faible</option>\n        <option value=\"medium\" selected>Moyenne</option>\n        <option value=\"high\">Élevée</option>\n        <option value=\"critical\">Critique — bloquant</option>\n      </select>\n\n      <label for=\"bugReportDesc\" style=\"font-size:12.5px;font-weight:600;color:var(--ink-soft);display:block;margin-bottom:6px;\">Décrivez le problème rencontré</label>\n      <textarea id=\"bugReportDesc\" rows=\"6\" placeholder=\"Ex. : le bouton Enregistrer ne répond pas quand je...\" style=\"width:100%;padding:10px 12px;border:1px solid var(--line);border-radius:8px;font-family:var(--font-sans);font-size:13.5px;resize:vertical;box-sizing:border-box;\"></textarea>\n      <div style=\"font-size:11.5px;color:var(--ink-soft);margin-top:8px;line-height:1.4;\">La page actuelle, votre navigateur et les éventuelles erreurs techniques récentes sont joints automatiquement pour aider au diagnostic.</div>\n\n      <label style=\"font-size:12.5px;font-weight:600;color:var(--ink-soft);display:block;margin-top:16px;margin-bottom:6px;\">Capture d'écran (facultatif)</label>\n      <input type=\"file\" id=\"bugReportImageInput\" accept=\"image/*\" style=\"display:none;\">\n      <!-- Même style de zone que \"Ajouter un ou plusieurs PDF\" dans la fiche\n           produit (retour utilisateur : cohérence entre les fenêtres) —\n           glisser-déposer et collage (Ctrl/Cmd+V) supportés en plus du clic. -->\n      <label id=\"bugReportImageDropzone\" for=\"bugReportImageInput\" style=\"display:flex;align-items:center;gap:8px;padding:10px 14px;border-radius:8px;border:1.5px dashed var(--line);background:var(--paper);color:var(--ink-soft);font-size:13px;cursor:pointer;font-family:inherit;\">\n        <i class=\"ti ti-photo-plus\" style=\"font-size:18px;color:var(--copper);\"></i>\n        Glisser une image, coller (Ctrl/Cmd+V) ou cliquer pour choisir\n      </label>\n      <div id=\"bugReportImagePreviewWrap\" style=\"display:none;margin-top:10px;\">\n        <div style=\"position:relative;width:fit-content;\">\n          <img id=\"bugReportImagePreview\" style=\"max-width:100%;max-height:160px;border-radius:8px;border:1px solid var(--line);display:block;cursor:zoom-in;\">\n          <button type=\"button\" id=\"bugReportImageRemove\" title=\"Retirer l'image\" style=\"position:absolute;top:-8px;right:-8px;width:24px;height:24px;border-radius:50%;background:#1e293b;color:#fff;border:none;cursor:pointer;font-size:14px;line-height:1;\">✕</button>\n        </div>\n      </div>\n    </div>\n    <div class=\"modal-foot\">\n      <div class=\"left-foot\"></div>\n      <div style=\"display:flex; gap:10px;\">\n        <button class=\"secondary\" id=\"bugReportCancelBtn\" type=\"button\">Annuler</button>\n        <!-- min-width : bascule vers \"Envoi…\" pendant l'envoi (js/requests.js)\n             — écart mesuré faible (~3px) mais gratuit à figer tant qu'on est\n             dessus, même principe que les autres boutons de cette passe. -->\n        <button class=\"copper\" id=\"bugReportSubmitBtn\" type=\"button\" style=\"min-width:95px;\">Envoyer</button>\n      </div>\n    </div>\n  </div>\n");
  // ── Conflits de synchronisation (#conflictOverlay) ──
  set("conflictOverlay", "\n  <div id=\"conflictModal\" style=\"background:var(--paper-card);border-radius:14px;width:100%;max-width:900px;max-height:90vh;display:flex;flex-direction:column;overflow:hidden;box-shadow:0 24px 80px rgba(0,0,0,.32);\">\n    <div style=\"padding:18px 24px;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;flex-shrink:0;\">\n      <div>\n        <div style=\"font-size:16px;font-weight:700;color:var(--ink);\"><i class=\"ti ti-alert-triangle\"></i> Conflits de synchronisation</div>\n        <div id=\"conflictSubtitle\" style=\"font-size:13px;color:var(--ink-soft);margin-top:2px;\"></div>\n      </div>\n      <button id=\"conflictCloseBtn\" style=\"background:none;border:none;font-size:20px;cursor:pointer;color:var(--ink-soft);padding:4px 8px;\">✕</button>\n    </div>\n    <div style=\"display:flex;flex:1;overflow:hidden;min-height:0;\">\n      <div id=\"conflictList\" style=\"width:220px;flex-shrink:0;border-right:1px solid var(--line);overflow-y:auto;padding:8px 0;box-sizing:border-box;\"></div>\n      <div id=\"conflictDetail\" style=\"flex:1;overflow-y:auto;padding:20px;min-width:0;\"></div>\n    </div>\n    <div style=\"padding:14px 24px;border-top:1px solid var(--line);display:flex;gap:10px;justify-content:flex-end;flex-shrink:0;\">\n      <button id=\"conflictKeepAllLocal\" style=\"padding:9px 18px;border:1.5px solid var(--line);border-radius:8px;background:var(--paper-card);color:var(--ink);font-size:13px;cursor:pointer;font-family:inherit;\">Garder tout le local</button>\n      <button id=\"conflictKeepAllServer\" style=\"padding:9px 18px;border:1.5px solid var(--line);border-radius:8px;background:var(--paper-card);color:var(--ink);font-size:13px;cursor:pointer;font-family:inherit;\">Garder tout le serveur</button>\n      <button id=\"conflictApplyBtn\" style=\"padding:9px 22px;border:none;border-radius:8px;background:#194093;color:#fff;font-size:13px;font-weight:600;cursor:pointer;font-family:inherit;\">Appliquer les choix</button>\n    </div>\n  </div>\n");
  // ── Documents (#docOverlay) ──
  set("docOverlay", "\n  <div id=\"docModal\" style=\"background:var(--paper-card);border-radius:14px;width:100%;max-width:700px;max-height:90vh;display:flex;flex-direction:column;overflow:hidden;box-shadow:0 24px 80px rgba(0,0,0,.3);\">\n    <div style=\"padding:18px 24px;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;flex-shrink:0;\">\n      <div style=\"font-size:15px;font-weight:700;color:var(--ink);\"><i class=\"ti ti-files\"></i> Documents produit</div>\n      <button id=\"docCloseBtn\" style=\"background:none;border:none;font-size:20px;cursor:pointer;color:var(--ink-soft);padding:4px 8px;\">✕</button>\n    </div>\n    <div id=\"docList\" style=\"flex:1;overflow-y:auto;padding:20px;min-height:0;\"></div>\n  </div>\n");
  // ── Suggestions (#sugOverlay) ──
  set("sugOverlay", "\n  <div id=\"sugModal\" style=\"background:var(--paper-card);border-radius:14px;width:100%;max-width:700px;max-height:90vh;display:flex;flex-direction:column;overflow:hidden;box-shadow:0 24px 80px rgba(0,0,0,.3);\">\n    <div style=\"padding:18px 24px;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;flex-shrink:0;\">\n      <div style=\"font-size:15px;font-weight:700;color:var(--ink);\" id=\"sugModalTitle\"><i class=\"ti ti-bulb\"></i> Produits suggérés</div>\n      <button id=\"sugCloseBtn\" style=\"background:none;border:none;font-size:20px;cursor:pointer;color:var(--ink-soft);padding:4px 8px;\">✕</button>\n    </div>\n    <div id=\"sugList\" style=\"flex:1;overflow-y:auto;padding:20px;min-height:0;\"></div>\n  </div>\n");
  // ── Parcourir le catalogue (sélection) (#sugPickerOverlay) ──
  set("sugPickerOverlay", "\n  <div id=\"sugPickerModal\" style=\"background:var(--paper-card);border-radius:14px;width:100%;max-width:880px;max-height:90vh;display:flex;flex-direction:column;overflow:hidden;box-shadow:0 24px 80px rgba(0,0,0,.3);\">\n    <div style=\"padding:18px 24px;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;flex-shrink:0;\">\n      <div style=\"font-size:15px;font-weight:700;color:var(--ink);\" id=\"sugPickerTitle\"><i class=\"ti ti-folder-open\"></i> Parcourir le catalogue</div>\n      <button id=\"sugPickerCloseBtn\" style=\"background:none;border:none;font-size:20px;cursor:pointer;color:var(--ink-soft);padding:4px 8px;\">✕</button>\n    </div>\n    <div style=\"padding:14px 24px 0;flex-shrink:0;\">\n      <input type=\"text\" id=\"sugPickerSearch\" placeholder=\"Filtrer par réf, nom, marque…\" style=\"width:100%;padding:9px 12px;border:1px solid var(--line);border-radius:6px;background:var(--paper);color:var(--ink);box-sizing:border-box;font-size:14px;\">\n    </div>\n    <div id=\"sugPickerList\" style=\"flex:1;overflow-y:auto;padding:16px 24px;min-height:0;\"></div>\n    <div style=\"padding:14px 24px;border-top:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;flex-shrink:0;gap:12px;\">\n      <span id=\"sugPickerCount\" style=\"font-size:13px;color:var(--ink-soft);\">0 sélectionné</span>\n      <div style=\"display:flex;gap:10px;\">\n        <button type=\"button\" class=\"secondary\" id=\"sugPickerCancelBtn\">Annuler</button>\n        <button type=\"button\" class=\"copper\" id=\"sugPickerSaveBtn\">Enregistrer</button>\n      </div>\n    </div>\n  </div>\n");
  // ── Caractéristiques techniques (#specsOverlay) ──
  set("specsOverlay", "\n  <div id=\"specsModal\" style=\"background:var(--paper-card);border-radius:14px;width:100%;max-width:560px;max-height:90vh;display:flex;flex-direction:column;overflow:hidden;box-shadow:0 24px 80px rgba(0,0,0,.3);\">\n    <div style=\"padding:18px 24px;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;gap:10px;flex-shrink:0;\">\n      <div style=\"font-size:15px;font-weight:700;color:var(--ink);flex:1;min-width:0;\"><i class=\"ti ti-tool\"></i> Caractéristiques techniques</div>\n      <button type=\"button\" id=\"specsDeleteAllBtn\" title=\"Tout supprimer\" style=\"background:none;border:1px solid var(--line);border-radius:7px;color:#991B1B;cursor:pointer;font-size:12px;font-weight:600;padding:6px 10px;font-family:var(--font-sans);display:flex;align-items:center;gap:5px;flex-shrink:0;\">\n        <i class=\"ti ti-trash\" style=\"font-size:14px;\"></i> Tout supprimer\n      </button>\n      <button id=\"specsCloseBtn\" style=\"background:none;border:none;font-size:20px;cursor:pointer;color:var(--ink-soft);padding:4px 8px;flex-shrink:0;\">✕</button>\n    </div>\n    <div style=\"flex:1;overflow-y:auto;padding:20px;min-height:0;\">\n      <div id=\"specsColHeaders\" style=\"display:none;grid-template-columns:minmax(0,1fr) minmax(0,1fr) 32px;gap:8px;padding:0 2px 6px;font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:.04em;color:var(--ink-soft);\">\n        <span>Nom</span><span>Valeur</span><span></span>\n      </div>\n      <div id=\"specsRows\" style=\"display:flex;flex-direction:column;gap:8px;\"></div>\n      <button type=\"button\" id=\"btnAddSpecRow\" style=\"margin-top:12px;background:none;border:1.5px dashed var(--line);border-radius:8px;color:var(--ink-soft);cursor:pointer;font-size:12.5px;font-weight:600;padding:8px 14px;font-family:var(--font-sans);\">+ Ajouter une caractéristique</button>\n    </div>\n    <div style=\"padding:14px 20px;border-top:1px solid var(--line);flex-shrink:0;\">\n      <button type=\"button\" id=\"specsSaveBtn\" style=\"width:100%;padding:10px;border:none;border-radius:9px;background:var(--copper);color:#fff;font-size:13px;font-weight:600;cursor:pointer;font-family:var(--font-sans);\">Enregistrer</button>\n    </div>\n  </div>\n");
  // ── Configurateur d'armoire (admin) (#armoireConfigOverlay) ──
  set("armoireConfigOverlay", "\n  <div id=\"armoireConfigModal\" style=\"background:var(--paper-card);border-radius:14px;width:100%;max-width:1120px;height:min(820px,90vh);display:flex;flex-direction:column;overflow:hidden;box-shadow:0 24px 80px rgba(0,0,0,.3);\">\n    <div style=\"padding:16px 22px;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;flex-shrink:0;\">\n      <div style=\"font-size:15px;font-weight:700;color:var(--ink);\"><i class=\"ti ti-tools\"></i> Configurateur d'armoire</div>\n      <button id=\"armoireConfigCloseBtn\" style=\"background:none;border:none;font-size:20px;cursor:pointer;color:var(--ink-soft);padding:4px 8px;\">✕</button>\n    </div>\n\n    <!-- Bascule mobile : une seule colonne visible à la fois, plein écran\n         (caché sur desktop où les deux colonnes restent côte à côte). -->\n    <div class=\"armoire-mobile-switch\" style=\"display:none;padding:10px 16px 0;flex-shrink:0;\">\n      <div class=\"tabs\">\n        <button type=\"button\" class=\"armoire-mobile-tab tab-btn active\" data-view=\"browse\"><i class=\"ti ti-search\"></i> Parcourir</button>\n        <button type=\"button\" class=\"armoire-mobile-tab tab-btn\" data-view=\"draft\"><i class=\"ti ti-shopping-cart\"></i> Ma configuration<span id=\"armoireMobileDraftBadge\" style=\"display:none;\"></span></button>\n      </div>\n    </div>\n\n    <div class=\"armoire-cfg-body\" style=\"flex:1;min-height:0;display:flex;overflow:hidden;\">\n\n      <!-- Colonne recherche produits -->\n      <div class=\"armoire-cfg-browse\" style=\"flex:2;min-width:0;display:flex;flex-direction:column;border-right:1px solid var(--line);overflow:hidden;position:relative;\">\n        <div style=\"padding:14px 16px;border-bottom:1px solid var(--line);flex-shrink:0;display:flex;gap:8px;align-items:center;\">\n          <input type=\"text\" id=\"armoireConfigSearch\" placeholder=\"Rechercher un produit (réf, nom)…\" style=\"flex:1;min-width:0;box-sizing:border-box;height:38px;padding:9px 12px;border:1px solid var(--line);border-radius:8px;font-size:13px;background:var(--paper);color:var(--ink);\">\n          <button type=\"button\" id=\"armoireBlocksDrawerTrigger\" style=\"flex-shrink:0;box-sizing:border-box;height:38px;display:flex;align-items:center;gap:6px;padding:0 12px;border-radius:8px;border:1px solid var(--copper);background:var(--paper);color:var(--copper-deep);font-size:12.5px;font-weight:600;cursor:pointer;white-space:nowrap;\"><i class=\"ti ti-package\" style=\"font-size:15px;\" aria-hidden=\"true\"></i> Blocs</button>\n        </div>\n        <div id=\"armoireConfigSearchResults\" style=\"flex:1;overflow-y:auto;padding:8px 10px;min-height:120px;\"></div>\n\n        <!-- Tiroir \"Blocs enregistrés / Configurations enregistrées\" — masqué par défaut, ouvert\n             à la demande par-dessus la liste de familles au lieu d'être empilé\n             en permanence dessous (retour utilisateur : ça compressait la liste\n             de familles). Voir _armoireOpenBlocksDrawer/_armoireCloseBlocksDrawer\n             dans armoireConfig.js. -->\n        <div id=\"armoireBlocksDrawer\" class=\"armoire-blocks-drawer\" style=\"display:none;\">\n          <div style=\"padding:12px 16px;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;flex-shrink:0;gap:8px;\">\n            <div class=\"tabs\">\n              <button type=\"button\" class=\"armoire-tab-btn tab-btn active\" data-tab=\"blocks\"><i class=\"ti ti-package\"></i> Blocs</button>\n              <button type=\"button\" class=\"armoire-tab-btn tab-btn\" data-tab=\"configs\"><i class=\"ti ti-clipboard-list\"></i> Configurations</button>\n            </div>\n            <button type=\"button\" id=\"armoireBlocksDrawerClose\" style=\"background:none;border:none;font-size:18px;cursor:pointer;color:var(--ink-soft);padding:2px 6px;flex-shrink:0;\">✕</button>\n          </div>\n          <div id=\"armoireConfigBlocksList\" style=\"flex:1;overflow-y:auto;padding:10px 14px;box-sizing:border-box;\"></div>\n          <div id=\"armoireConfigSavedList\" style=\"display:none;flex:1;overflow-y:auto;padding:10px 14px;box-sizing:border-box;\"></div>\n        </div>\n      </div>\n\n      <!-- Colonne configuration en cours -->\n      <div class=\"armoire-cfg-draft\" style=\"flex:1;min-width:260px;display:flex;flex-direction:column;overflow:hidden;\">\n        <div style=\"padding:14px 16px;border-bottom:1px solid var(--line);flex-shrink:0;\">\n          <div style=\"display:flex;align-items:center;justify-content:space-between;\">\n            <div style=\"font-size:13px;font-weight:700;color:var(--ink);\">Configuration en cours</div>\n            <button type=\"button\" id=\"armoireConfigClearBtn\" style=\"background:none;border:none;color:var(--ink-soft);font-size:12px;cursor:pointer;\">Vider</button>\n          </div>\n          <div id=\"armoireConfigStats\" style=\"display:flex;margin-top:8px;gap:8px;\"></div>\n        </div>\n        <div id=\"armoireEditingBanner\" style=\"display:none;align-items:center;justify-content:space-between;gap:8px;padding:8px 14px;background:#FFF7ED;border-bottom:1px solid #FDE68A;font-size:12px;color:#92400E;flex-shrink:0;\">\n          <span id=\"armoireEditingBannerText\" style=\"display:flex;align-items:center;gap:6px;\"><i class=\"ti ti-pencil\"></i></span>\n          <button type=\"button\" id=\"armoireEditingCancelBtn\" style=\"background:none;border:none;color:#92400E;font-size:12px;font-weight:600;cursor:pointer;text-decoration:underline;flex-shrink:0;\">Annuler</button>\n        </div>\n        <div id=\"armoireConfigDraftList\" style=\"flex:1;overflow-y:auto;padding:10px 14px;\"></div>\n        <div style=\"padding:12px 14px;border-top:1px solid var(--line);flex-shrink:0;display:flex;flex-direction:column;gap:8px;\">\n          <button type=\"button\" id=\"armoireConfigExportBtn\" style=\"width:100%;padding:10px;border-radius:8px;border:1px solid #cfe0bd;background:#eef4e8;color:#3b6d11;font-size:12.5px;font-weight:600;cursor:pointer;display:flex;align-items:center;justify-content:center;gap:7px;\"><i class=\"ti ti-file-spreadsheet\" style=\"font-size:15px;\" aria-hidden=\"true\"></i> Exporter en Excel <span style=\"font-weight:500;opacity:.75;\">(par fournisseur)</span></button>\n          <button type=\"button\" id=\"armoireConfigQuoteBtn\" style=\"width:100%;padding:10px;border-radius:8px;border:1px solid var(--copper);background:var(--paper);color:var(--copper-deep);font-size:12.5px;font-weight:600;cursor:pointer;display:flex;align-items:center;justify-content:center;gap:7px;\"><i class=\"ti ti-mail\" style=\"font-size:15px;\" aria-hidden=\"true\"></i> Demande de devis</button>\n          <button type=\"button\" id=\"armoireConfigSaveBtn\" style=\"width:100%;padding:10px;border-radius:8px;border:none;background:var(--copper);color:#fff;font-size:12.5px;font-weight:600;cursor:pointer;display:flex;align-items:center;justify-content:center;gap:7px;\"><i class=\"ti ti-device-floppy\" style=\"font-size:15px;\" aria-hidden=\"true\"></i> Enregistrer</button>\n        </div>\n      </div>\n\n    </div>\n  </div>\n");
  // ── Lecteur PDF (#pdfViewerOverlay) ──
  set("pdfViewerOverlay", "\n  <div style=\"background:#1a1a1a;border-radius:14px;width:100%;max-width:1040px;height:94vh;display:flex;flex-direction:column;overflow:hidden;box-shadow:0 24px 80px rgba(0,0,0,.6);\">\n    <!-- Header -->\n    <div style=\"display:flex;align-items:center;justify-content:space-between;padding:10px 16px;background:#2a2a2a;flex-shrink:0;border-bottom:1px solid rgba(255,255,255,.08);\">\n      <div style=\"display:flex;align-items:center;gap:8px;min-width:0;flex:1;\">\n        <!-- Icône adaptée au type de fichier (PDF/image) — voir\n             _pdfUpdateTypeIcon dans js/render-pdf-viewer.js, retour utilisateur :\n             \"faut que l'icône de la visionneuse s'adapte au fichier\". -->\n        <i id=\"pdfViewerTypeIcon\" class=\"ti ti-file-type-pdf\" style=\"font-size:17px;color:#E53E3E;flex-shrink:0;\"></i>\n        <span id=\"pdfViewerTitle\" style=\"font-size:13px;font-weight:600;color:#fff;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;\"></span>\n      </div>\n      <!-- Rechercher dans le document — retour utilisateur : \"est-ce qu'on\n           peut faire des recherches sur un pdf ?\". Toujours affiché (pas\n           conditionné au nombre de pages, contrairement à la nav de page) ;\n           masqué uniquement pour une image (voir _pdfUpdateSearchUI dans\n           js/render-pdf-viewer.js — une image n'a pas de texte à chercher). -->\n      <button id=\"pdfViewerSearchToggle\" title=\"Rechercher dans le document\" aria-label=\"Rechercher dans le document\" style=\"background:none;border:none;font-size:16px;cursor:pointer;color:rgba(255,255,255,.7);padding:4px 6px;line-height:1;display:flex;align-items:center;flex-shrink:0;margin:0 4px;\"><i class=\"ti ti-search\" aria-hidden=\"true\"></i></button>\n      <!-- Navigation page — PDF multi-pages uniquement (masqué pour un PDF\n           d'1 seule page ou une image, voir _pdfUpdatePageNavUI dans\n           js/render-pdf-viewer.js). Chevrons haut/bas (pas gauche/droite) : les pages\n           s'empilent verticalement dans #pdfViewerScroll, \"suivant\" fait\n           donc défiler vers le bas — retour utilisateur : \"numéro de page /\n           navigation\" sur les PDF multi-pages. Le numéro courant est un\n           champ saisissable (pas juste affiché) — retour utilisateur : \"est\n           qu'on peut rentrer le numéro d'une page ?\" — Entrée ou perte de\n           focus saute directement à la page tapée (voir _pdfJumpFromInput\n           dans js/render-pdf-viewer.js), une saisie invalide/hors bornes revient\n           simplement sur la page réelle plutôt que de planter. -->\n      <div id=\"pdfViewerPageNav\" style=\"display:none;align-items:center;gap:3px;flex-shrink:0;margin:0 6px;\">\n        <button id=\"pdfViewerPrevPage\" title=\"Page précédente\" aria-label=\"Page précédente\" style=\"background:none;border:none;font-size:17px;cursor:pointer;color:rgba(255,255,255,.7);padding:4px 5px;line-height:1;display:flex;align-items:center;\"><i class=\"ti ti-chevron-up\" aria-hidden=\"true\"></i></button>\n        <input id=\"pdfViewerPageInput\" type=\"text\" inputmode=\"numeric\" pattern=\"[0-9]*\" aria-label=\"Aller à la page\" style=\"width:26px;background:rgba(255,255,255,.1);border:1px solid rgba(255,255,255,.25);border-radius:4px;color:#fff;font-size:12px;text-align:center;padding:3px 2px;font-variant-numeric:tabular-nums;font-family:inherit;\">\n        <span id=\"pdfViewerPageTotal\" style=\"font-size:12px;color:rgba(255,255,255,.6);white-space:nowrap;font-variant-numeric:tabular-nums;\"></span>\n        <button id=\"pdfViewerNextPage\" title=\"Page suivante\" aria-label=\"Page suivante\" style=\"background:none;border:none;font-size:17px;cursor:pointer;color:rgba(255,255,255,.7);padding:4px 5px;line-height:1;display:flex;align-items:center;\"><i class=\"ti ti-chevron-down\" aria-hidden=\"true\"></i></button>\n      </div>\n      <!-- Zoom — jusqu'ici uniquement possible au pincement tactile (mobile),\n           donc inaccessible à la souris/au trackpad sur desktop (retour\n           utilisateur : \"il y a que tout mobile\"). Boutons +/- réutilisant\n           exactement le même mécanisme de zoom que le pincement\n           (_pdfSetZoom/_pdfSharpenPages, voir js/render-pdf-viewer.js), ancrés sur le\n           centre de la zone visible plutôt que le point du doigt (qui\n           n'existe pas au clic). Toujours affiché (contrairement à la nav\n           de page, pas conditionné au nombre de pages) — pertinent même\n           sur un document d'1 page ou une image. -->\n      <div id=\"pdfViewerZoomControls\" style=\"display:flex;align-items:center;gap:2px;flex-shrink:0;margin:0 6px;\">\n        <button id=\"pdfViewerZoomOut\" title=\"Zoom arrière\" aria-label=\"Zoom arrière\" style=\"background:none;border:none;font-size:16px;cursor:pointer;color:rgba(255,255,255,.7);padding:4px 5px;line-height:1;display:flex;align-items:center;\"><i class=\"ti ti-zoom-out\" aria-hidden=\"true\"></i></button>\n        <span id=\"pdfViewerZoomLabel\" style=\"font-size:12px;color:rgba(255,255,255,.85);white-space:nowrap;min-width:38px;text-align:center;font-variant-numeric:tabular-nums;\">100%</span>\n        <button id=\"pdfViewerZoomIn\" title=\"Zoom avant\" aria-label=\"Zoom avant\" style=\"background:none;border:none;font-size:16px;cursor:pointer;color:rgba(255,255,255,.7);padding:4px 5px;line-height:1;display:flex;align-items:center;\"><i class=\"ti ti-zoom-in\" aria-hidden=\"true\"></i></button>\n        <!-- Réinitialiser le zoom à 100% en un clic — retour utilisateur :\n             \"est-ce qu'on peut ajouter un bouton pour reset le zoom ?\".\n             Désactivé quand déjà à 100% (rien à réinitialiser). -->\n        <button id=\"pdfViewerZoomReset\" title=\"Réinitialiser le zoom (100%)\" aria-label=\"Réinitialiser le zoom\" style=\"background:none;border:none;font-size:15px;cursor:pointer;color:rgba(255,255,255,.7);padding:4px 5px;line-height:1;display:flex;align-items:center;margin-left:2px;\"><i class=\"ti ti-zoom-reset\" aria-hidden=\"true\"></i></button>\n      </div>\n      <button id=\"pdfViewerClose\" style=\"background:none;border:none;font-size:22px;cursor:pointer;color:rgba(255,255,255,.6);padding:0 4px;line-height:1;flex-shrink:0;\">✕</button>\n    </div>\n    <!-- Barre de recherche — masquée par défaut, affichée en cliquant sur\n         la loupe ci-dessus. Entrée = résultat suivant, Échap = fermer (voir\n         _initPdfSearch dans js/render-pdf-viewer.js). -->\n    <div id=\"pdfViewerSearchBar\" style=\"display:none;align-items:center;gap:6px;padding:8px 16px;background:#232323;border-bottom:1px solid rgba(255,255,255,.08);flex-shrink:0;\">\n      <i class=\"ti ti-search\" style=\"color:rgba(255,255,255,.4);font-size:14px;flex-shrink:0;\" aria-hidden=\"true\"></i>\n      <input id=\"pdfViewerSearchInput\" type=\"text\" placeholder=\"Rechercher dans le document…\" autocomplete=\"off\" style=\"flex:1;min-width:0;background:rgba(255,255,255,.08);border:1px solid rgba(255,255,255,.2);border-radius:6px;color:#fff;font-size:13px;padding:6px 10px;font-family:inherit;\">\n      <span id=\"pdfViewerSearchCount\" style=\"font-size:12px;color:rgba(255,255,255,.55);white-space:nowrap;min-width:56px;text-align:center;font-variant-numeric:tabular-nums;\"></span>\n      <button id=\"pdfViewerSearchPrev\" title=\"Occurrence précédente\" aria-label=\"Occurrence précédente\" style=\"background:none;border:none;font-size:16px;cursor:pointer;color:rgba(255,255,255,.7);padding:4px 5px;line-height:1;display:flex;align-items:center;flex-shrink:0;\"><i class=\"ti ti-chevron-up\" aria-hidden=\"true\"></i></button>\n      <button id=\"pdfViewerSearchNext\" title=\"Occurrence suivante\" aria-label=\"Occurrence suivante\" style=\"background:none;border:none;font-size:16px;cursor:pointer;color:rgba(255,255,255,.7);padding:4px 5px;line-height:1;display:flex;align-items:center;flex-shrink:0;\"><i class=\"ti ti-chevron-down\" aria-hidden=\"true\"></i></button>\n      <button id=\"pdfViewerSearchClose\" title=\"Fermer la recherche\" aria-label=\"Fermer la recherche\" style=\"background:none;border:none;font-size:16px;cursor:pointer;color:rgba(255,255,255,.7);padding:4px 5px;line-height:1;display:flex;align-items:center;flex-shrink:0;\"><i class=\"ti ti-x\" aria-hidden=\"true\"></i></button>\n    </div>\n    <!-- Loader -->\n    <div id=\"pdfViewerLoader\" style=\"display:flex;align-items:center;justify-content:center;flex:1;flex-direction:column;gap:14px;\">\n      <i class=\"ti ti-loader-2\" style=\"font-size:36px;color:#fff;animation:spin 1s linear infinite;\"></i>\n      <span style=\"font-size:13px;color:rgba(255,255,255,.5);\">Chargement…</span>\n    </div>\n    <!-- Rendu PDF.js sur canvas — permet le pincement pour zoomer sur mobile,\n         impossible à intercepter avec l'ancien lecteur natif en iframe. Le\n         zoom redimensionne directement les canvas (pas de transform CSS) pour\n         que le défilement fonctionne de façon fiable sur iOS Safari. -->\n    <div id=\"pdfViewerScroll\" style=\"display:none;flex:1;overflow:auto;background:#525252;\">\n      <div id=\"pdfViewerPages\"></div>\n    </div>\n  </div>\n");
})();
